47	/**
48	 * The helper class to handle no response process. An independent thread will be created on demand
49	 * so the caller can report the ANR without worrying about taking long time.
50	 */
51	class AnrHelper {
52	    private static final String TAG = TAG_WITH_CLASS_NAME ? "AnrHelper" : TAG_AM;
53	
54	    /**
55	     * If the system is extremely slow somehow that the ANR has been pending too long for more than
56	     * this time, the information might be outdated. So we only the dump the unresponsive process
57	     * instead of including other processes to avoid making the system more busy.
58	     */
59	    private static final long EXPIRED_REPORT_TIME_MS = TimeUnit.SECONDS.toMillis(10);
60	
61	    /**
62	     * If the last ANR occurred within this given time, consider it's anomaly.
63	     */
64	    private static final long CONSECUTIVE_ANR_TIME_MS = TimeUnit.MINUTES.toMillis(2);
65	
66	    /**
67	     * Time to wait before taking dumps for other processes to reduce load at boot time.
68	     */
69	    private static final long SELF_ONLY_AFTER_BOOT_MS = TimeUnit.MINUTES.toMillis(10);
70	
71	    /**
72	     * The keep alive time for the threads in the helper threadpool executor
73	    */
74	    private static final int DEFAULT_THREAD_KEEP_ALIVE_SECOND = 10;
75	
76	    private static final ThreadFactory sDefaultThreadFactory =  r ->
77	            new Thread(r, "AnrAuxiliaryTaskExecutor");
78	    private static final ThreadFactory sMainProcessDumpThreadFactory =  r ->
79	            new Thread(r, "AnrMainProcessDumpThread");
80	
81	    @GuardedBy("mAnrRecords")
82	    private final ArrayList<AnrRecord> mAnrRecords = new ArrayList<>();
83	
84	    private final Set<Integer> mTempDumpedPids =
85	            Collections.synchronizedSet(new ArraySet<Integer>());
86	
87	    private final AtomicBoolean mRunning = new AtomicBoolean(false);
88	
89	    private final ActivityManagerService mService;
90	
91	    /**
92	     * The timestamp when the last ANR occurred.
93	     */
94	    private long mLastAnrTimeMs = 0L;
95	
96	    /** The pid which is running appNotResponding(). */
97	    @GuardedBy("mAnrRecords")
98	    private int mProcessingPid = -1;
99	
100	    private final ExecutorService mAuxiliaryTaskExecutor;
101	    private final ExecutorService mEarlyDumpExecutor;
102	
103	    AnrHelper(final ActivityManagerService service) {
104	        // All the ANR threads need to expire after a period of inactivity, given the
105	        // ephemeral nature of ANRs and how infrequent they are.
106	        this(service, makeExpiringThreadPoolWithSize(1, sDefaultThreadFactory),
107	                makeExpiringThreadPoolWithSize(2, sMainProcessDumpThreadFactory));
108	    }
109	
110	    @VisibleForTesting
111	    AnrHelper(ActivityManagerService service, ExecutorService auxExecutor,
112	            ExecutorService earlyDumpExecutor) {
113	        mService = service;
114	        mAuxiliaryTaskExecutor = auxExecutor;
115	        mEarlyDumpExecutor = earlyDumpExecutor;
116	    }
117	
118	    void appNotResponding(ProcessRecord anrProcess, TimeoutRecord timeoutRecord) {
119	        appNotResponding(anrProcess, null /* activityShortComponentName */, null /* aInfo */,
120	                null /* parentShortComponentName */, null /* parentProcess */,
121	                false /* aboveSystem */, timeoutRecord, /*isContinuousAnr*/ false);
122	    }
123	
124	    void appNotResponding(ProcessRecord anrProcess, String activityShortComponentName,
125	            ApplicationInfo aInfo, String parentShortComponentName,
126	            WindowProcessController parentProcess, boolean aboveSystem,
127	            TimeoutRecord timeoutRecord, boolean isContinuousAnr) {
128	        try {
129	            timeoutRecord.mLatencyTracker.appNotRespondingStarted();
130	            final int incomingPid = anrProcess.mPid;
131	            timeoutRecord.mLatencyTracker.waitingOnAnrRecordLockStarted();
132	            synchronized (mAnrRecords) {
133	                timeoutRecord.mLatencyTracker.waitingOnAnrRecordLockEnded();
134	                if (incomingPid == 0) {
135	                    // Extreme corner case such as zygote is no response
136	                    // to return pid for the process.
137	                    Slog.i(TAG, "Skip zero pid ANR, process=" + anrProcess.processName);
138	                    return;
139	                }
140	                if (mProcessingPid == incomingPid) {
141	                    Slog.i(TAG,
142	                            "Skip duplicated ANR, pid=" + incomingPid + " "
143	                            + timeoutRecord.mReason);
144	                    return;
145	                }
146	                if (!mTempDumpedPids.add(incomingPid)) {
147	                    Slog.i(TAG,
148	                            "Skip ANR being predumped, pid=" + incomingPid + " "
149	                            + timeoutRecord.mReason);
150	                    return;
151	                }
152	                for (int i = mAnrRecords.size() - 1; i >= 0; i--) {
153	                    if (mAnrRecords.get(i).mPid == incomingPid) {
154	                        Slog.i(TAG,
155	                                "Skip queued ANR, pid=" + incomingPid + " "
156	                                + timeoutRecord.mReason);
157	                        return;
158	                    }
159	                }
160	                // We dump the main process as soon as we can on a different thread,
161	                // this is done as the main process's dump can go stale in a few hundred
162	                // milliseconds and the average full ANR dump takes a few seconds.
163	                timeoutRecord.mLatencyTracker.earlyDumpRequestSubmittedWithSize(
164	                        mTempDumpedPids.size());
165	                Future<File> firstPidDumpPromise = mEarlyDumpExecutor.submit(() -> {
166	                    // the class AnrLatencyTracker is not generally thread safe but the values
167	                    // recorded/touched by the Temporary dump thread(s) are all volatile/atomic.
168	                    File tracesFile = StackTracesDumpHelper.dumpStackTracesTempFile(incomingPid,
169	                            timeoutRecord.mLatencyTracker);
170	                    mTempDumpedPids.remove(incomingPid);
171	                    return tracesFile;
172	                });
173	
174	                timeoutRecord.mLatencyTracker.anrRecordPlacingOnQueueWithSize(mAnrRecords.size());
175	                mAnrRecords.add(new AnrRecord(anrProcess, activityShortComponentName, aInfo,
176	                        parentShortComponentName, parentProcess, aboveSystem, timeoutRecord,
177	                        isContinuousAnr, firstPidDumpPromise));
178	            }
179	            startAnrConsumerIfNeeded();
180	        } finally {
181	            timeoutRecord.mLatencyTracker.appNotRespondingEnded();
182	        }
183	
184	    }
185	
186	    private void startAnrConsumerIfNeeded() {
187	        if (mRunning.compareAndSet(false, true)) {
188	            new AnrConsumerThread().start();
189	        }
190	    }
191	
192	    private static ThreadPoolExecutor makeExpiringThreadPoolWithSize(int size,
193	            ThreadFactory factory) {
194	        ThreadPoolExecutor pool = new ThreadPoolExecutor(/* corePoolSize= */ size,
195	                /* maximumPoolSize= */ size, /* keepAliveTime= */ DEFAULT_THREAD_KEEP_ALIVE_SECOND,
196	                TimeUnit.SECONDS, new LinkedBlockingQueue<>(), factory);
197	        // We allow the core threads to expire after the keepAliveTime.
198	        pool.allowCoreThreadTimeOut(true);
199	        return pool;
200	    }
201	
202	    /**
203	     * The thread to execute {@link ProcessErrorStateRecord#appNotResponding}. It will terminate if
204	     * all records are handled.
205	     */
206	    private class AnrConsumerThread extends Thread {
207	        AnrConsumerThread() {
208	            super("AnrConsumer");
209	        }
210	
211	        private AnrRecord next() {
212	            synchronized (mAnrRecords) {
213	                if (mAnrRecords.isEmpty()) {
214	                    return null;
215	                }
216	                final AnrRecord record = mAnrRecords.remove(0);
217	                mProcessingPid = record.mPid;
218	                record.mTimeoutRecord.mLatencyTracker.anrRecordsQueueSizeWhenPopped(
219	                        mAnrRecords.size());
220	                return record;
221	            }
222	        }
223	
224	        @Override
225	        public void run() {
226	            AnrRecord r;
227	            while ((r = next()) != null) {
228	                scheduleBinderHeavyHitterAutoSamplerIfNecessary();
229	                final int currentPid = r.mApp.mPid;
230	                if (currentPid != r.mPid) {
231	                    // The process may have restarted or died.
232	                    Slog.i(TAG, "Skip ANR with mismatched pid=" + r.mPid + ", current pid="
233	                            + currentPid);
234	                    continue;
235	                }
236	                final long startTime = SystemClock.uptimeMillis();
237	                // If there are many ANR at the same time, the latency may be larger.
238	                // If the latency is too large, the stack trace might not be meaningful.
239	                final long reportLatency = startTime - r.mTimestamp;
240	                final boolean onlyDumpSelf = reportLatency > EXPIRED_REPORT_TIME_MS
241	                        || startTime < SELF_ONLY_AFTER_BOOT_MS;
242	                r.appNotResponding(onlyDumpSelf);
243	                final long endTime = SystemClock.uptimeMillis();
244	
245	                if (android.os.profiling.Flags.systemTriggeredProfilingNew() && r.mAppInfo != null
246	                        && r.mAppInfo.packageName != null) {
247	                    ProfilingServiceHelper.getInstance().onProfilingTriggerOccurred(
248	                            r.mUid,
249	                            r.mAppInfo.packageName,
250	                            ProfilingTrigger.TRIGGER_TYPE_ANR);
251	                }
252	
253	                Slog.d(TAG, "Completed ANR of " + r.mApp.processName + " in "
254	                        + (endTime - startTime) + "ms, latency " + reportLatency
255	                        + (onlyDumpSelf ? "ms (expired, only dump ANR app)" : "ms"));
256	            }
257	
258	            mRunning.set(false);
259	            synchronized (mAnrRecords) {
260	                mProcessingPid = -1;
261	                // The race should be unlikely to happen. Just to make sure we don't miss.
262	                if (!mAnrRecords.isEmpty()) {
263	                    startAnrConsumerIfNeeded();
264	                }
265	            }
266	        }
267	
268	    }
269	
270	    private void scheduleBinderHeavyHitterAutoSamplerIfNecessary() {
271	        try {
272	            Trace.traceBegin(Trace.TRACE_TAG_ACTIVITY_MANAGER,
273	                    "scheduleBinderHeavyHitterAutoSamplerIfNecessary()");
274	            final long now = SystemClock.uptimeMillis();
275	            if (mLastAnrTimeMs + CONSECUTIVE_ANR_TIME_MS > now) {
276	                mService.scheduleBinderHeavyHitterAutoSampler();
277	            }
278	            mLastAnrTimeMs = now;
279	        } finally {
280	            Trace.traceEnd(Trace.TRACE_TAG_ACTIVITY_MANAGER);
281	        }
282	    }
283	
284	    private class AnrRecord {
285	        final ProcessRecord mApp;
286	        final int mPid;
287	        final int mUid;
288	        final String mActivityShortComponentName;
289	        final String mParentShortComponentName;
290	        final TimeoutRecord mTimeoutRecord;
291	        final ApplicationInfo mAppInfo;
292	        final WindowProcessController mParentProcess;
293	        final boolean mAboveSystem;
294	        final long mTimestamp = SystemClock.uptimeMillis();
295	        final boolean mIsContinuousAnr;
296	        final Future<File> mFirstPidFilePromise;
297	        AnrRecord(ProcessRecord anrProcess, String activityShortComponentName,
298	                ApplicationInfo aInfo, String parentShortComponentName,
299	                WindowProcessController parentProcess, boolean aboveSystem,
300	                TimeoutRecord timeoutRecord, boolean isContinuousAnr,
301	                Future<File> firstPidFilePromise) {
302	            mApp = anrProcess;
303	            mPid = anrProcess.mPid;
304	            mUid = anrProcess.uid;
305	            mActivityShortComponentName = activityShortComponentName;
306	            mParentShortComponentName = parentShortComponentName;
307	            mTimeoutRecord = timeoutRecord;
308	            mAppInfo = aInfo;
309	            mParentProcess = parentProcess;
310	            mAboveSystem = aboveSystem;
311	            mIsContinuousAnr = isContinuousAnr;
312	            mFirstPidFilePromise = firstPidFilePromise;
313	        }
314	
315	        void appNotResponding(boolean onlyDumpSelf) {
316	            try {
317	                mTimeoutRecord.mLatencyTracker.anrProcessingStarted();
318	                mApp.mErrorState.appNotResponding(mActivityShortComponentName, mAppInfo,
319	                        mParentShortComponentName, mParentProcess, mAboveSystem,
320	                        mTimeoutRecord, mAuxiliaryTaskExecutor, onlyDumpSelf,
321	                        mIsContinuousAnr, mFirstPidFilePromise);
322	            } finally {
323	                mTimeoutRecord.mLatencyTracker.anrProcessingEnded();
324	            }
325	        }
326	    }
327	}
