756	    private @Nullable LinkedHashMap<String, String> buildMemoryHeadersFor(int pid) {
757	        if (pid <= 0) {
758	            Slog.i(TAG, "Memory header requested with invalid pid: " + pid);
759	            return null;
760	        }
761	        MemorySnapshot snapshot = readMemorySnapshotFromProcfs(pid);
762	        if (snapshot == null) {
763	            Slog.i(TAG, "Failed to get memory snapshot for pid:" + pid);
764	            return null;
765	        }
766	
767	        LinkedHashMap<String, String> memoryHeaders = new LinkedHashMap<>();
768	        memoryHeaders.put("RssHwmKb", Integer.toString(snapshot.rssHighWaterMarkInKilobytes));
769	        memoryHeaders.put("RssKb", Integer.toString(snapshot.rssInKilobytes));
770	        memoryHeaders.put("RssAnonKb", Integer.toString(snapshot.anonRssInKilobytes));
771	        memoryHeaders.put("RssShmemKb", Integer.toString(snapshot.rssShmemKilobytes));
772	        memoryHeaders.put("VmSwapKb", Integer.toString(snapshot.swapInKilobytes));
773	        return memoryHeaders;
774	    }
