800	    void dump(PrintWriter pw, String prefix, long nowUptime) {
801	        synchronized (mProcLock) {
802	            if (mCrashing || mDialogController.hasCrashDialogs() || mNotResponding
803	                    || mDialogController.hasAnrDialogs() || mBad) {
804	                pw.print(prefix);
805	                pw.print(" mCrashing=" + mCrashing);
806	                pw.print(" " + mDialogController.getCrashDialogs());
807	                pw.print(" mNotResponding=" + mNotResponding);
808	                pw.print(" " + mDialogController.getAnrDialogs());
809	                pw.print(" bad=" + mBad);
810	
811	                // mCrashing or mNotResponding is always set before errorReportReceiver
812	                if (mErrorReportReceiver != null) {
813	                    pw.print(" errorReportReceiver=");
814	                    pw.print(mErrorReportReceiver.flattenToShortString());
815	                }
816	                pw.println();
817	            }
818	        }
