139	     * {@link #mProcessCrashCounts} and {@link #mBadProcesses}.
140	     *
141	     * <p>The naming convention of the function with this lock should be "-LBp"</b>
142	     *
143	     * @See mBadProcesses
144	     */
145	    private final Object mBadProcessLock = new Object();
