38	final class AppNotRespondingDialog extends BaseErrorDialog implements View.OnClickListener {
39	    private static final String TAG = "AppNotRespondingDialog";
40	
41	    // Event 'what' codes
42	    static final int FORCE_CLOSE = 1;
43	    static final int WAIT = 2;
44	    static final int WAIT_AND_REPORT = 3;
45	
46	    public static final int CANT_SHOW = -1;
47	    public static final int ALREADY_SHOWING = -2;
48	
49	    private final ActivityManagerService mService;
50	    private final ProcessRecord mProc;
51	    private final Data mData;
52	
53	    public AppNotRespondingDialog(ActivityManagerService service, Context context, Data data) {
54	        super(context);
55	
56	        mService = service;
57	        mProc = data.proc;
58	        mData = data;
59	        Resources res = context.getResources();
60	
61	        setCancelable(false);
62	
63	        int resid;
64	        CharSequence name1 = data.aInfo != null
65	                ? data.aInfo.loadLabel(context.getPackageManager())
66	                : null;
67	        CharSequence name2 = null;
68	        if (mProc.getPkgList().size() == 1
69	                && (name2 = context.getPackageManager().getApplicationLabel(mProc.info)) != null) {
70	            if (name1 != null) {
71	                resid = com.android.internal.R.string.anr_activity_application;
72	            } else {
73	                name1 = name2;
74	                name2 = mProc.processName;
75	                resid = com.android.internal.R.string.anr_application_process;
76	            }
77	        } else {
78	            if (name1 != null) {
79	                name2 = mProc.processName;
80	                resid = com.android.internal.R.string.anr_activity_process;
81	            } else {
82	                name1 = mProc.processName;
83	                resid = com.android.internal.R.string.anr_process;
84	            }
85	        }
86	
87	        BidiFormatter bidi = BidiFormatter.getInstance();
88	
89	        setTitle(name2 != null
90	                ? res.getString(resid, bidi.unicodeWrap(name1.toString()), bidi.unicodeWrap(name2.toString()))
91	                : res.getString(resid, bidi.unicodeWrap(name1.toString())));
92	
93	        if (data.aboveSystem) {
94	            getWindow().setType(WindowManager.LayoutParams.TYPE_SYSTEM_ERROR);
95	        }
96	        WindowManager.LayoutParams attrs = getWindow().getAttributes();
97	        attrs.setTitle("Application Not Responding: " + mProc.info.processName);
98	        attrs.privateFlags = WindowManager.LayoutParams.PRIVATE_FLAG_SYSTEM_ERROR |
99	                WindowManager.LayoutParams.SYSTEM_FLAG_SHOW_FOR_ALL_USERS;
100	        getWindow().setAttributes(attrs);
101	    }
102	
103	    @Override
104	    protected void onCreate(Bundle savedInstanceState) {
105	        super.onCreate(savedInstanceState);
106	        final FrameLayout frame = findViewById(android.R.id.custom);
107	        final Context context = getContext();
108	        LayoutInflater.from(context).inflate(
109	                com.android.internal.R.layout.app_anr_dialog, frame, true);
110	
111	        final TextView report = findViewById(com.android.internal.R.id.aerr_report);
112	        report.setOnClickListener(this);
113	        final boolean hasReceiver = mProc.mErrorState.getErrorReportReceiver() != null;
114	        report.setVisibility(hasReceiver ? View.VISIBLE : View.GONE);
115	        final TextView close = findViewById(com.android.internal.R.id.aerr_close);
116	        close.setOnClickListener(this);
117	        final TextView wait = findViewById(com.android.internal.R.id.aerr_wait);
118	        wait.setOnClickListener(this);
119	
120	        findViewById(com.android.internal.R.id.customPanel).setVisibility(View.VISIBLE);
121	    }
122	
123	    @Override
124	    public void onClick(View v) {
125	        switch (v.getId()) {
126	            case com.android.internal.R.id.aerr_report:
127	                mHandler.obtainMessage(WAIT_AND_REPORT).sendToTarget();
128	                break;
129	            case com.android.internal.R.id.aerr_close:
130	                mHandler.obtainMessage(FORCE_CLOSE).sendToTarget();
131	                break;
132	            case com.android.internal.R.id.aerr_wait:
133	                mHandler.obtainMessage(WAIT).sendToTarget();
134	                break;
135	            default:
136	                break;
137	        }
138	    }
139	
140	    private final Handler mHandler = new Handler() {
141	        public void handleMessage(Message msg) {
142	            Intent appErrorIntent = null;
143	
144	            MetricsLogger.action(getContext(), MetricsProto.MetricsEvent.ACTION_APP_ANR,
145	                    msg.what);
146	
147	            switch (msg.what) {
148	                case FORCE_CLOSE:
149	                    // Kill the application.
150	                    mService.killAppAtUsersRequest(mProc);
151	                    break;
152	                case WAIT_AND_REPORT:
153	                case WAIT:
154	                    // Continue waiting for the application.
155	                    synchronized (mService) {
156	                        ProcessRecord app = mProc;
157	                        final ProcessErrorStateRecord errState = app.mErrorState;
158	
159	                        if (msg.what == WAIT_AND_REPORT) {
160	                            appErrorIntent = mService.mAppErrors.createAppErrorIntentLOSP(app,
161	                                    System.currentTimeMillis(), null);
162	                        }
163	
164	                        synchronized (mService.mProcLock) {
165	                            errState.setNotResponding(false);
166	                            // We're not clearing the ANR report here, in case we'd need to report
167	                            // it again when the ANR dialog shows again.
168	                            // errState.setNotRespondingReport(null);
169	                            errState.getDialogController().clearAnrDialogs();
170	                        }
171	                        mService.mServices.scheduleServiceTimeoutLocked(app);
172	                        if (mData.isContinuousAnr) {
173	                            // If the app remains unresponsive, show the dialog again after a delay.
174	                            mService.mInternal.rescheduleAnrDialog(mData);
175	                        }
176	                    }
177	                    break;
178	            }
179	
180	            if (appErrorIntent != null) {
181	                try {
182	                    getContext().startActivity(appErrorIntent);
183	                } catch (ActivityNotFoundException e) {
184	                    Slog.w(TAG, "bug report receiver dissappeared", e);
185	                }
186	            }
187	
188	            dismiss();
189	        }
190	    };
191	
192	    @Override
193	    protected void closeDialog() {
194	        mHandler.obtainMessage(FORCE_CLOSE).sendToTarget();
195	    }
196	
197	    static class Data {
198	        final ProcessRecord proc;
199	        final ApplicationInfo aInfo;
200	        final boolean aboveSystem;
201	
202	        // If true, then even if the user presses "WAIT" on the ANR dialog,
203	        // we'll show it again until the app start responding again.
204	        // (we only use it for input dispatch ANRs)
205	        final boolean isContinuousAnr;
206	
207	        Data(ProcessRecord proc, ApplicationInfo aInfo, boolean aboveSystem,
208	                boolean isContinuousAnr) {
209	            this.proc = proc;
210	            this.aInfo = aInfo;
211	            this.aboveSystem = aboveSystem;
212	            this.isContinuousAnr = isContinuousAnr;
213	        }
214	    }
215	}
