17	package com.android.server.am;
18	
19	import static android.content.Context.RECEIVER_EXPORTED;
20	
21	import android.app.AlertDialog;
22	import android.content.BroadcastReceiver;
23	import android.content.Context;
24	import android.content.Intent;
25	import android.content.IntentFilter;
26	import android.os.Handler;
27	import android.os.Message;
28	import android.view.KeyEvent;
29	import android.view.WindowManager;
30	import android.widget.Button;
31	
32	import com.android.internal.R;
33	
34	public class BaseErrorDialog extends AlertDialog {
35	    private static final int ENABLE_BUTTONS = 0;
36	    private static final int DISABLE_BUTTONS = 1;
37	
38	    private boolean mConsuming = true;
39	    private BroadcastReceiver mReceiver;
40	
41	    public BaseErrorDialog(Context context) {
42	        super(context, com.android.internal.R.style.Theme_DeviceDefault_Dialog_AppError);
43	        context.assertRuntimeOverlayThemable();
44	
45	        getWindow().setType(WindowManager.LayoutParams.TYPE_SYSTEM_ALERT);
46	        getWindow().setFlags(WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM,
47	                WindowManager.LayoutParams.FLAG_ALT_FOCUSABLE_IM);
48	        WindowManager.LayoutParams attrs = getWindow().getAttributes();
49	        attrs.setTitle("Error Dialog");
50	        getWindow().setAttributes(attrs);
51	    }
52	
53	    @Override
54	    public void onStart() {
55	        super.onStart();
56	        mHandler.sendEmptyMessage(DISABLE_BUTTONS);
57	        mHandler.sendMessageDelayed(mHandler.obtainMessage(ENABLE_BUTTONS), 1000);
58	        if (mReceiver == null) {
59	            mReceiver = new BroadcastReceiver() {
60	                @Override
61	                public void onReceive(Context context, Intent intent) {
62	                    if (Intent.ACTION_CLOSE_SYSTEM_DIALOGS.equals(intent.getAction())) {
63	                        closeDialog();
64	                    }
65	                }
66	            };
67	            getContext().registerReceiver(mReceiver,
68	                    new IntentFilter(Intent.ACTION_CLOSE_SYSTEM_DIALOGS), RECEIVER_EXPORTED);
69	        }
70	    }
71	
72	    @Override
73	    protected void onStop() {
74	        super.onStop();
75	        if (mReceiver != null) {
76	            try {
77	                getContext().unregisterReceiver(mReceiver);
78	            } catch (IllegalArgumentException e) {
79	                // Receiver not registered exception.
80	                android.util.Slog.e("BaseErrorDialog",
81	                        "unregisterReceiver threw exception: " + e.getMessage());
82	            }
83	            mReceiver = null;
84	        }
85	    }
86	
87	    public boolean dispatchKeyEvent(KeyEvent event) {
88	        if (mConsuming) {
89	            //Slog.i(TAG, "Consuming: " + event);
90	            return true;
91	        }
92	        //Slog.i(TAG, "Dispatching: " + event);
93	        return super.dispatchKeyEvent(event);
94	    }
95	
96	    private void setEnabled(boolean enabled) {
97	        Button b = (Button)findViewById(R.id.button1);
98	        if (b != null) {
99	            b.setEnabled(enabled);
100	        }
101	        b = (Button)findViewById(R.id.button2);
102	        if (b != null) {
103	            b.setEnabled(enabled);
104	        }
105	        b = (Button)findViewById(R.id.button3);
106	        if (b != null) {
107	            b.setEnabled(enabled);
108	        }
109	    }
110	
111	    private Handler mHandler = new Handler() {
112	        public void handleMessage(Message msg) {
113	            if (msg.what == ENABLE_BUTTONS) {
114	                mConsuming = false;
115	                setEnabled(true);
116	            } else if (msg.what == DISABLE_BUTTONS) {
117	                setEnabled(false);
118	            }
119	        }
120	    };
121	
122	    /**
123	     * Called when received ACTION_CLOSE_SYSTEM_DIALOGS.
124	     */
125	    protected void closeDialog() {
126	        if (mCancelable) {
127	            cancel();
128	        } else {
129	            dismiss();
130	        }
131	    }
132	}
